actions.script:
const report = ec.service.sync().name('org.moqui.admin.DataTransferServices.get#ImportSample')
    .parameters({targetId:targetId, kindId:kindId, organizationPartyId:organizationPartyId}).call() || {}
if (ec.message.hasError()) ec.web.sendJsonResponse({})
else ec.web.sendTextResponse(report.reportCsv, 'text/csv', report.filename)

const report = ec.service.sync().name('org.moqui.admin.DataTransferServices.get#ImportReport')
    .parameters({targetId:targetId, operationKey:operationKey, errorsOnly:(errorsOnly == 'true' || errorsOnly === true)}).call() || {}
if (ec.message.hasError()) ec.web.sendJsonResponse({})
else ec.web.sendTextResponse(report.reportCsv, 'text/csv', report.filename)
